import './dashboard.css';
const q=new URLSearchParams(location.search);
const selected={framework:q.get('framework')||'tailwind4',order:q.get('order')||'early',theme:q.get('theme')||'light'};
const policies=[['default','Goober default','Unlayered styles injected at runtime'],['layered','With cascade layer','Component styles inside a native CSS layer'],['adapted','With owned styles','Generated Goober CSS; only the library’s sheet is inserted']];
const select=(key,choices)=>`<label>${key}<select id="${key}">${choices.map(([v,label])=>`<option value="${v}" ${selected[key]===v?'selected':''}>${label}</option>`).join('')}</select></label>`;
document.querySelector('#app').innerHTML=`<main><header><p class="eyebrow">OPENUI / GOOBER-ONLY PROTOTYPE</p><h1>Does Goober meet our requirements?</h1><p><a href="/performance.html">Open the streaming performance lab →</a></p><p class="intro">Same representative controls, three integration policies. Check automatic styling, Tailwind overrides, themes, portals, and source traceability. This is throwaway evidence, not a production migration.</p></header><section class="controls">${select('framework',[['none','No framework'],['tailwind3','Tailwind v3'],['tailwind4','Tailwind v4'],['bootstrap','Bootstrap 5'],['plain','Plain CSS']])}${select('order',[['early','Consumer CSS before component'],['late','Consumer CSS after component']])}${select('theme',[['light','Light theme'],['dark','Dark theme']])}</section><aside><strong>Read the difference:</strong> the library button should keep its own style. The consumer override button should take the framework’s color and padding. The adapter is prototype code we would have to own; Goober does not automatically detect frameworks. The updated adapter leaves the host’s Goober sheet untouched. Framework selection is still explicit in this experiment.</aside><section class="grid">${policies.map(([key,label,sub])=>`<article><div class="card-head"><h2>${label}</h2><p>${sub}</p></div><iframe title="${label} fixture" src="/fixture?${new URLSearchParams({...selected,engine:'goober',policy:key})}"></iframe><details><summary>Inspect rendered styles & source</summary><pre id="trace-${key}">Loading…</pre></details></article>`).join('')}</section><section class="results"><h2>Automatic SSR, without app styling setup</h2><p>The new library component carries Goober-generated styles through React 19. The production Next.js checks cover server HTML, hydration, streamed content, navigation, repeated mounts, and concurrent requests.</p><p><a href="http://127.0.0.1:4179/" target="_blank" rel="noreferrer">Open the production SSR example</a> · <a href="/automatic" target="_blank" rel="noreferrer">Open plain React SSR</a> · <a href="/results/NEXT.md">Read SSR evidence</a></p><p>Package-build-generated static rules and React 19 are required for this path. This reference SSR example is framework-free; the installed-package examples above combine SSR with automatic framework setup.</p></section><section class="results"><h2>Generated compatibility report</h2><p>Measured from real compiled Tailwind v3/v4 and Bootstrap CSS, plus a plain stylesheet. Failures are intentionally retained. This is small-fixture evidence, not universal framework certification.</p><div id="results">Run the check command to generate results.</div></section><footer>Checks cover Chromium, classic React SSR/hydration, and a production Next.js App Router fixture. Full OpenUI parity and all browser/framework configurations are not certified. Sources, exact versions, and the structured report are retained with the prototype.</footer></main>`;
for(const key of Object.keys(selected))document.querySelector('#'+key).onchange=e=>{q.set(key,e.target.value);location.search=q.toString();};
for(const frame of document.querySelectorAll('iframe'))frame.onload=()=>{const timer=setInterval(()=>{if(!frame.contentWindow.__ready)return;clearInterval(timer);const el=frame.contentDocument.querySelector('[data-testid=baseline]');const st=frame.contentWindow.getComputedStyle(el);const policy=frame.contentWindow.__fixture.policy;document.querySelector('#trace-'+policy).textContent=JSON.stringify({source:el.dataset.source,component:el.dataset.openuiComponent,className:el.className,background:st.backgroundColor,padding:st.padding,policy},null,2);},100);};
fetch('/results/results.json').then(r=>r.ok?r.json():null).then(data=>{if(!data)return;const rows=data.cases.filter(c=>c.order===selected.order);document.querySelector('#results').innerHTML=`<table><thead><tr><th>Policy</th><th>Framework</th><th>Base</th><th>Override</th><th>Hover</th><th>Portal</th><th>No rule growth</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${c.policy}</td><td>${c.framework}</td>${['base','override','hover','portal','stableRules'].map(k=>`<td class="${c.checks[k]?'pass':'fail'}">${c.checks[k]?'Pass':'Fail'}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}).catch(()=>{});
fetch('/results/manifest.json').then(r=>r.ok?r.json():null).then(data=>{if(!data)return;const section=document.createElement('section');section.className='results';section.innerHTML='<h2>Does Goober satisfy the full requirement set?</h2><p>Goober supplies the styling engine. Some requirements need OpenUI tooling or framework integration; the prototype leaves those gaps visible.</p><table><thead><tr><th>Requirement</th><th>Observed result</th><th>Responsibility</th></tr></thead><tbody>'+data.requirements.map(x=>`<tr><td>${x.requirement}</td><td>${x.status}</td><td>${x.owner}</td></tr>`).join('')+'</tbody></table>';document.querySelector('footer').before(section);}).catch(()=>{});

fetch('/results/compatibility.json').then(r=>r.ok?r.json():null).then(data=>{
 if(!data)return;
 const section=document.createElement('section');section.className='results';
 section.innerHTML='<h2>Latest: installed package + production SSR</h2><p><strong>Executed checks: '+data.passed+'/'+data.total+'.</strong> The installer places generated CSS before app CSS automatically. No hand editing or SSR registry is needed. All installed variant styles load up front, including streamed content. These checks use the installed tarball, not source imports.</p><table><thead><tr><th>Browser</th><th>Framework</th><th>Result</th><th>Failing checks</th></tr></thead><tbody>'+data.results.map(r=>{const failed=Object.entries(r.checks).filter(([,v])=>!v).map(([k])=>k);return '<tr><td>'+r.browser+'</td><td>'+r.framework+'</td><td class="'+(failed.length?'fail':'pass')+'">'+(failed.length?'Fail':'Pass')+'</td><td>'+failed.join(', ')+'</td></tr>'}).join('')+'</tbody></table><p>Firefox: unavailable on this host (launch failure). <a href="/results/COMPATIBILITY.md">Full evidence</a> · <a href="/results/CSP.md">CSP checks</a></p><p>Live installed-package examples: <a href="http://127.0.0.1:4211" target="_blank" rel="noreferrer">Tailwind v3</a> · <a href="http://127.0.0.1:4212" target="_blank" rel="noreferrer">Tailwind v4</a> · <a href="http://127.0.0.1:4214" target="_blank" rel="noreferrer">Plain CSS</a></p>';
 document.querySelector('header').after(section);
}).catch(()=>{});
